let lessons = [
 {id: 1, title: 'Introduction to JavaScript', learn: 'Understand JS', summary: 'Learn syntax'},
 {id: 2, title: 'Variables and Data Types', learn: 'Store info', summary: 'Learn let, const'},
 {id: 3, title: 'Operators', learn: 'Perform calculations', summary: 'Master operators'}
];
let completed = 2;

// Simulate your dashboard's renderLessons
function createLessonCard(lesson, completed) {
 let isCompleted = lesson.id <= completed;
 let isCurrent = lesson.id === completed + 1;
 let isLocked = lesson.id > completed + 1;

 let status = isCompleted? 'completed' : isCurrent? 'current' : 'locked';
 let button = isLocked? 'Locked' : isCompleted? 'Review' : 'Start Lesson';

 return {
 id: lesson.id,
 title: lesson.title,
 status,
 button,
 element: `Article card for ${lesson.title} with ${status} badge and ${button} button`
 };
}

function renderLessons(completed) {
 console.log('Step 1: Clear container - lessonContainer.innerHTML = ""');
 let lessonContainer = { innerHTML: 'old content', children: [] };
 lessonContainer.innerHTML = ""; // Clear

 console.log('Step 2: Create grid div with class lesson-grid');
 let grid = { className: 'lesson-grid', cards: [] };

 console.log('Step 3: Loop through lessons with forEach and create cards');
 lessons.forEach(lesson => {
 let card = createLessonCard(lesson, completed);
 grid.cards.push(card);
 console.log(` - Created card: Lesson ${lesson.id} ${lesson.title} - ${card.status} - ${card.button}`);
 });

 console.log(`Step 4: Append grid with ${grid.cards.length} cards to container - 1 reflow, efficient`);
 lessonContainer.children.push(grid);

 console.log(`\nRendered ${grid.cards.length} cards in grid`);
 return lessonContainer;
}

