const TOTAL_LESSONS = 10;
let lessons = [
 {id: 1, title: 'Introduction to JavaScript', status: 'completed', xp: 100, coins: 10},
 {id: 2, title: 'Variables and Data Types', status: 'completed', xp: 100, coins: 10},
 {id: 3, title: 'Operators and Expressions', status: 'current', xp: 0, coins: 0},
 {id: 4, title: 'Conditions', status: 'locked', xp: 0, coins: 0},
 {id: 5, title: 'Loops', status: 'locked', xp: 0, coins: 0},
 {id: 6, title: 'Functions', status: 'locked', xp: 0, coins: 0},
 {id: 7, title: 'Arrays and Objects', status: 'locked', xp: 0, coins: 0},
 {id: 8, title: 'DOM Manipulation', status: 'locked', xp: 0, coins: 0},
 {id: 9, title: 'Events and Modern JS', status: 'locked', xp: 0, coins: 0},
 {id: 10, title: 'Build Website', status: 'locked', xp: 0, coins: 0}
];

let completed = 2;
let xp = 200;
let coins = 20;

// Function to get status - like your dashboard
function getStatus(lessonId) {
 if (lessonId <= completed) return "completed";
 if (lessonId === completed + 1) return "current";
 return "locked";
}

// Function to create card - like your createLessonCard
function createLessonCard(lesson) {
 let status = getStatus(lesson.id);
 let button = status === 'locked'? 'Locked' : status === 'completed'? 'Review' : 'Start Lesson';
 return { id: lesson.id, title: lesson.title, status, button, xp: lesson.xp };
}

// Render all lessons - forEach like your dashboard
console.log("=== RENDERING ALL LESSONS (forEach) ===");
let grid = [];
lessons.forEach(lesson => {
 let card = createLessonCard(lesson);
 grid.push(card);
 console.log(`${card.id}. ${card.title} - ${card.status.toUpperCase()} - [${card.button}]`);
});

// Count with for...of and continue
console.log("\n=== COUNTING WITH for...of + continue ===");
let completedCount = 0;
let currentCount = 0;
let lockedCount = 0;
for (let lesson of lessons) {
 let status = getStatus(lesson.id);
 if (status === 'completed') {
 completedCount++;
 continue; // Skip rest, go to next
 }
 if (status === 'current') {
 currentCount++;
 continue;
 }
 lockedCount++;
}
console.log(`Completed: ${completedCount}, Current: ${currentCount}, Locked: ${lockedCount}`);

// Search with for loop + break
console.log("\n=== SEARCHING WITH for + break ===");
function findLesson(id) {
 for (let i = 0; i < lessons.length; i++) {
 if (lessons[i].id === id) {
 console.log(`Found lesson ${id} at index ${i}: ${lessons[i].title}`);
 return lessons[i]; // Or break and return after loop
 }
 }
 console.log(`Lesson ${id} not found`);
 return null;
}
findLesson(3);
findLesson(10);
findLesson(15);

// Calculate total XP with for loop
console.log("\n=== TOTAL XP WITH for LOOP ===");
let totalXPEarned = 0;
for (let i = 0; i < lessons.length; i++) {
 totalXPEarned += lessons[i].xp; // += assignment
}
console.log(`Total XP earned: ${totalXPEarned}`);

