console.log("\n=== WHILE LOOP - LOADING WITH RETRIES ===");
let loading = true;
let retries = 0;
while (loading && retries < 3) {
 retries++;
 console.log(`Loading attempt ${retries}...`);
 if (retries === 2) {
 loading = false;
 console.log('Loaded successfully!');
 }
}
console.log(`Finished after ${retries} retries`);

// Progress with arithmetic and loop
console.log("\n=== PROGRESS CALCULATION ===");
let percent = Math.round((completed / TOTAL_LESSONS) * 100);
console.log(`Progress: ${completed}/${TOTAL_LESSONS} = ${percent}%`);
let progressBar = "";
for (let i = 0; i < 10; i++) { // 10 blocks for progress bar
 progressBar += i < percent / 10? "█" : "░";
}
console.log(`Progress bar: [${progressBar}] ${percent}%`);

// Nested loop - lessons and badges
console.log("\n=== NESTED LOOP - LESSONS AND STATS ===");
let stats = ['xp', 'coins', 'status'];
for (let lesson of lessons.slice(0, 3)) { // First 3 lessons
 console.log(`Lesson ${lesson.id}: ${lesson.title}`);
 for (let stat of stats) { // Inner loop
 if (stat === 'xp') console.log(` ${stat}: ${lesson.xp}`);
 if (stat === 'coins') console.log(` ${stat}: ${lesson.coins}`);
 if (stat === 'status') console.log(` ${stat}: ${getStatus(lesson.id)}`);
 }
}

console.log("\n=== FINAL DASHBOARD STATE ===");
